<?php require_once __DIR__.'/../includes/auth.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=$pdo->prepare('SELECT s.*,u.full_name FROM sales s LEFT JOIN users u ON u.id=s.user_id WHERE s.id=?');$st->execute([$id]);$sale=$st->fetch();if(!$sale){http_response_code(404);exit('Invoice not found.');}$st=$pdo->prepare('SELECT si.*,p.name,p.sku FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?');$st->execute([$id]);$items=$st->fetchAll();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice <?=e($sale['invoice_no'])?></title><link rel="stylesheet" href="../assets/css/style.css"><style>.print-wrap{max-width:850px;margin:35px auto;background:#fff;padding:42px;border:1px solid #e3e8f1}.print-actions{max-width:850px;margin:20px auto;display:flex;justify-content:flex-end;gap:8px}@media print{body{background:#fff}.print-actions{display:none}.print-wrap{margin:0;border:0;max-width:none;padding:0}}</style></head><body><div class="print-actions"><button class="btn primary" onclick="window.print()">Print invoice</button><button class="btn" onclick="window.close()">Close</button></div><div class="print-wrap"><div class="invoice-brand"><div class="brand-icon">▦</div><div><h1>SHOP INVOICE</h1><p>Shop & Inventory Management</p></div><div class="invoice-number"><small>Invoice</small><strong><?=e($sale['invoice_no'])?></strong></div></div><hr><div class="invoice-meta"><div><small>Invoice date</small><strong><?=e($sale['created_at'])?></strong></div><div><small>Payment method</small><strong>Cash</strong></div><div><small>Prepared by</small><strong><?=e($sale['full_name']??'Admin')?></strong></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Product</th><th>SKU</th><th>Price</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($items as $n=>$i):?><tr><td><?=$n+1?></td><td><?=e($i['name'])?></td><td><?=e($i['sku'])?></td><td><?=money($i['unit_price'])?></td><td><?=$i['quantity']?></td><td><?=money($i['line_total'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="5" class="align-right">Subtotal</th><th><?=money($sale['subtotal'])?></th></tr><tr><th colspan="5" class="align-right">Grand total</th><th><?=money($sale['grand_total'])?></th></tr></tfoot></table></div><p class="thank-you">Thank you for shopping with us!</p></div></body></html>
